// Reads connection details from the running local Supabase.
// Values are development-only keys generated by the Supabase CLI.
import { execFileSync } from "node:child_process";

export function readLocalSupabase() {
  let output;
  try {
    output = execFileSync("pnpm", ["exec", "supabase", "status", "--output", "json"], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    });
  } catch {
    console.error("Local Supabase is not running. Start it with `pnpm db:start`.");
    process.exit(1);
  }
  const start = output.indexOf("{");
  const status = JSON.parse(output.slice(start));
  const required = ["API_URL", "ANON_KEY", "SERVICE_ROLE_KEY", "DB_URL"];
  for (const key of required) {
    if (!status[key]) {
      console.error(`supabase status did not report ${key}.`);
      process.exit(1);
    }
  }
  return status;
}
